import { test, describe } from 'node:test';
import assert from 'node:assert/strict';

import { mapFinishReasonError, decideUploadPath, INLINE_SIZE_LIMIT_BYTES } from '../src/gemini-client-ocr-helpers.js';
import { runGeminiOcr } from '../src/tools/gemini_ocr.js';
import type { GeminiOcrDeps, DetectResult, RasterizeResult, OcrGenerateResult } from '../src/tools/gemini_ocr_types.js';
// isStructuredError lives in bundle.ts in the real gemini-server (not
// errors.ts, unlike the staging build) — real errors.ts only gained the
// `ocr_failed` code + `ocrFailed()` factory during integration.
import { isStructuredError } from '../src/bundle.js';

// ---------------------------------------------------------------------------
// finishReason -> actionable structured error mapping
// ---------------------------------------------------------------------------

describe('mapFinishReasonError', () => {
  test('STOP -> null (success, no error)', () => {
    assert.equal(mapFinishReasonError('STOP', 3), null);
  });

  test('MAX_TOKENS -> actionable error, not raw code', () => {
    const err = mapFinishReasonError('MAX_TOKENS', 7);
    assert.ok(err);
    assert.equal(err!.code, 'ocr_failed');
    assert.match(err!.message, /page 7/);
    assert.match(err!.message, /response_format=concise|smaller page_range/);
    assert.doesNotMatch(err!.message, /^finish_reason: /);
  });

  test('SAFETY -> actionable error mentioning the page and a next step', () => {
    const err = mapFinishReasonError('SAFETY', 7);
    assert.ok(err);
    assert.equal(err!.code, 'ocr_failed');
    assert.match(err!.message, /page 7/);
    assert.match(err!.message, /safety/i);
    assert.doesNotMatch(err!.message.toLowerCase(), /^finish_reason: safety$/);
  });

  test('RECITATION -> actionable error', () => {
    const err = mapFinishReasonError('RECITATION', 2);
    assert.ok(err);
    assert.equal(err!.code, 'ocr_failed');
    assert.match(err!.message, /recitation/i);
  });

  test('unexpected finishReason -> generic actionable fallback', () => {
    const err = mapFinishReasonError('OTHER', 1);
    assert.ok(err);
    assert.equal(err!.code, 'ocr_failed');
    assert.match(err!.message, /page 1/);
  });
});

// ---------------------------------------------------------------------------
// inline vs Files API payload-size decision
// ---------------------------------------------------------------------------

describe('decideUploadPath', () => {
  test('small payload stays inline', () => {
    const decision = decideUploadPath([100_000, 200_000]); // 300KB raw
    assert.equal(decision.useFilesApi, false);
  });

  test('payload estimated over 20MB base64 switches to Files API', () => {
    // Raw bytes chosen so base64 estimate (raw * 4/3) clears the 20MB limit.
    const rawBytes = Math.ceil(INLINE_SIZE_LIMIT_BYTES * 0.8); // ~16MB raw -> ~21.3MB base64
    const decision = decideUploadPath([rawBytes]);
    assert.equal(decision.useFilesApi, true);
    assert.ok(decision.estimatedBase64Bytes > INLINE_SIZE_LIMIT_BYTES);
  });

  test('boundary just under the limit stays inline', () => {
    const rawBytes = Math.floor((INLINE_SIZE_LIMIT_BYTES * 3) / 4) - 1000;
    const decision = decideUploadPath([rawBytes]);
    assert.equal(decision.useFilesApi, false);
  });
});

// ---------------------------------------------------------------------------
// runGeminiOcr integration (all deps mocked — no network, no real subprocess)
// ---------------------------------------------------------------------------

function makeDeps(overrides: Partial<GeminiOcrDeps> = {}): GeminiOcrDeps {
  const detect: DetectResult = {
    document_path: '/fake/doc.pdf',
    total_pages: 3,
    density_threshold_chars: 20,
    pages: [
      { page_number: 1, is_born_digital: true, char_count: 500, text: 'born digital page one' },
      { page_number: 2, is_born_digital: false, char_count: 0, text: '' },
      { page_number: 3, is_born_digital: false, char_count: 0, text: '' },
    ],
  };
  const raster: RasterizeResult = {
    temp_dir: '/tmp/fake-gemini-ocr',
    dpi: 250,
    pages: [
      { page_number: 2, png_path: '/tmp/fake-gemini-ocr/page-2.png' },
      { page_number: 3, png_path: '/tmp/fake-gemini-ocr/page-3.png' },
    ],
  };
  const cleanedUp: string[] = [];
  return {
    generate: async () =>
      ({
        text: JSON.stringify([
          { page_number: 2, text: 'scanned page two', is_born_digital: false, confidence: 'high', notes: '' },
          { page_number: 3, text: 'scanned page three', is_born_digital: false, confidence: 'high', notes: '' },
        ]),
        finishReason: 'STOP',
      }) satisfies OcrGenerateResult,
    runDetectTextLayer: async () => detect,
    runRasterizePages: async () => raster,
    readFileBase64: async () => ({ data: 'ZmFrZQ==', rawBytes: 1000 }),
    cleanupDir: async (dir: string) => {
      cleanedUp.push(dir);
    },
    fileExists: async () => true,
    ...overrides,
  };
}

describe('runGeminiOcr', () => {
  test('missing document_path -> actionable validation error, not raw ENOENT', async () => {
    const deps = makeDeps({ fileExists: async () => false });
    await assert.rejects(
      () => runGeminiOcr({ document_path: '/no/such/file.pdf', target_language: 'en' }, deps),
      (err: unknown) => {
        assert.ok(isStructuredError(err));
        const structured = err as { code: string; message: string };
        assert.equal(structured.code, 'validation');
        assert.match(structured.message, /does not exist/);
        assert.doesNotMatch(structured.message, /ENOENT/);
        return true;
      },
    );
  });

  test('bad target_language enum -> validation error before any I/O happens', async () => {
    let detectCalled = false;
    const deps = makeDeps({
      runDetectTextLayer: async () => {
        detectCalled = true;
        throw new Error('should not be called');
      },
    });
    await assert.rejects(() =>
      runGeminiOcr({ document_path: '/fake/doc.pdf', target_language: 'fr' }, deps),
    );
    assert.equal(detectCalled, false);
  });

  test('happy path: born-digital page skips Gemini, scanned pages get OCR text, sequential batches', async () => {
    const deps = makeDeps();
    const result = await runGeminiOcr(
      { document_path: '/fake/doc.pdf', target_language: 'he' },
      deps,
    );
    assert.equal(result.truncated, false);
    assert.equal(result.pages.length, 3);
    assert.deepEqual(
      result.pages.map((p) => p.page_number),
      [1, 2, 3],
    );
    const p1 = result.pages.find((p) => p.page_number === 1)!;
    assert.equal(p1.is_born_digital, true);
    assert.equal(p1.text, 'born digital page one');
    const p2 = result.pages.find((p) => p.page_number === 2)!;
    assert.equal(p2.is_born_digital, false);
    assert.equal(p2.text, 'scanned page two');
  });

  test('Gemini SAFETY finishReason surfaces as actionable ocr_failed error', async () => {
    const deps = makeDeps({
      generate: async () => ({ text: '[]', finishReason: 'SAFETY' }),
    });
    await assert.rejects(
      () => runGeminiOcr({ document_path: '/fake/doc.pdf', target_language: 'en' }, deps),
      (err: unknown) => {
        assert.ok(isStructuredError(err));
        const structured = err as { code: string; message: string };
        assert.equal(structured.code, 'ocr_failed');
        assert.match(structured.message, /safety/i);
        return true;
      },
    );
  });

  test('oversized batch payload routes to Files-API-not-wired error, not a broken inline call', async () => {
    const deps = makeDeps({
      readFileBase64: async () => ({ data: 'x'.repeat(100), rawBytes: 15_000_000 }), // 2 pages * 15MB raw > 20MB base64
    });
    await assert.rejects(
      () => runGeminiOcr({ document_path: '/fake/doc.pdf', target_language: 'en' }, deps),
      (err: unknown) => {
        assert.ok(isStructuredError(err));
        const structured = err as { code: string; message: string };
        assert.equal(structured.code, 'ocr_failed');
        assert.match(structured.message, /20MB|Files API/);
        return true;
      },
    );
  });

  test('temp dir is cleaned up even when the Gemini call fails', async () => {
    const cleaned: string[] = [];
    const deps = makeDeps({
      generate: async () => {
        throw new Error('simulated network failure');
      },
      cleanupDir: async (dir: string) => {
        cleaned.push(dir);
      },
    });
    await assert.rejects(() =>
      runGeminiOcr({ document_path: '/fake/doc.pdf', target_language: 'en' }, deps),
    );
    assert.deepEqual(cleaned, ['/tmp/fake-gemini-ocr']);
  });

  test('truncation: page_range larger than PER_CALL_PAGE_CAP reports continuation message', async () => {
    const bigTotal = 50;
    const detect: DetectResult = {
      document_path: '/fake/big.pdf',
      total_pages: bigTotal,
      density_threshold_chars: 20,
      pages: Array.from({ length: bigTotal }, (_, i) => ({
        page_number: i + 1,
        is_born_digital: true,
        char_count: 500,
        text: `page ${i + 1}`,
      })),
    };
    const deps = makeDeps({ runDetectTextLayer: async () => detect });
    const result = await runGeminiOcr(
      { document_path: '/fake/big.pdf', target_language: 'en' },
      deps,
    );
    assert.equal(result.truncated, true);
    assert.equal(result.pages.length, 40); // PER_CALL_PAGE_CAP
    assert.match(result.truncation_message!, /40 of 50 pages processed/);
    assert.match(result.truncation_message!, /page 41/);
  });
});
